// Wavelet Time-Frequency Analyzer (apps/wavelet_tf_analyzer.rs). Expected
// values: tests/fixtures/apps/wavelet_tf_analyzer/reference.json, generated by
// tool/refs/wavelet_tf_analyzer/wavelet_tf_analyzer.py (NumPy, published
// definitions; never MATLAB).
mod wavelet_tf_analyzer_tests {
    use super::*;
    use apps::wavelet_tf_analyzer::{Region, Transform, Wavelet, WaveletTfAnalyzer};
    use apps::{App, AppKind, Host, Snapshot};
    use toolkits::Tool;

    const TONES: &str = "t = (0:1023)/1024; x = cos(2*pi*40*t) + 0.5*sin(2*pi*90*t);";

    fn reference() -> serde_json::Value {
        serde_json::from_str(include_str!(
            "../../tests/fixtures/apps/wavelet_tf_analyzer/reference.json"
        ))
        .unwrap()
    }
    fn floats(v: &serde_json::Value) -> Vec<f64> {
        v.as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_f64().unwrap())
            .collect()
    }
    fn workspace(code: &str) -> (matrust::Engine, Snapshot) {
        let mut engine = matrust::Engine::default();
        engine.execute(code).unwrap();
        let mut ws = Snapshot::default();
        ws.sync(&engine.workspace());
        (engine, ws)
    }
    fn compute(host: &mut Host<WaveletTfAnalyzer>, ws: &Snapshot) -> Result<apps::Outputs, String> {
        host.app.prepare(ws);
        let outputs = apps::run(&mut matrust::Engine::default(), host.request(ws)?)?;
        host.app.receive(&outputs)?;
        Ok(outputs)
    }
    fn tones_host() -> Host<WaveletTfAnalyzer> {
        let mut host = Host::new(WaveletTfAnalyzer::default());
        host.app.settings.signal = "x".into();
        host.app.settings.rate = "1024".into();
        host
    }
    /// Runs the saved script (header included) in a fresh Engine holding the
    /// workspace's variables.
    fn run_saved(host: &mut Host<WaveletTfAnalyzer>, ws: &Snapshot) -> matrust::Engine {
        let script = host.app.script(ws).unwrap();
        let saved = match host.generate(ws, 42).unwrap() {
            toolkits::Action::SaveAppScript(AppKind::WaveletTfAnalyzer, text) => text,
            _ => panic!("wrong save action"),
        };
        assert!(saved.ends_with(&script));
        let mut fresh = matrust::Engine::default();
        for (name, a) in ws.variables() {
            fresh.insert_array(name, a.clone()).unwrap();
        }
        fresh.execute(&saved).unwrap();
        fresh
    }
    fn real(engine: &matrust::Engine, name: &str) -> Vec<f64> {
        match engine.array(name).unwrap() {
            matrust::Array::Numeric(m) => m.data().to_vec(),
            a => panic!("{name}: {}", a.class()),
        }
    }
    fn complex(engine: &matrust::Engine, name: &str) -> (Vec<f64>, Vec<f64>) {
        match engine.array(name).unwrap() {
            matrust::Array::Complex(c) => (
                c.data().iter().map(|z| z.re).collect(),
                c.data().iter().map(|z| z.im).collect(),
            ),
            a => panic!("{name}: {}", a.class()),
        }
    }
    /// |got - want| <= tol * max(1, |want|), element by element.
    fn all_close(got: &[f64], want: &[f64], tol: f64, what: &str) {
        assert_eq!(got.len(), want.len(), "{what}: length");
        for (k, (g, w)) in got.iter().zip(want).enumerate() {
            assert!(
                (g - w).abs() <= tol * w.abs().max(1.),
                "{what}[{k}]: {g} != {w}"
            );
        }
    }
    fn every(v: &[f64], step: usize) -> Vec<f64> {
        v.iter().step_by(step).copied().collect()
    }
    fn check_coefficients(engine: &matrust::Engine, name: &str, want: &serde_json::Value) {
        let step = 97;
        let (re, im) = complex(engine, name);
        all_close(&every(&re, step), &floats(&want["re"]), 1e-10, "real part");
        all_close(
            &every(&im, step),
            &floats(&want["im"]),
            1e-10,
            "imaginary part",
        );
    }

    #[test]
    fn wavelet_tf_analyzer_two_tone_cwt_matches_reference_and_script() {
        let reference = reference();
        let want = &reference["cwt"];
        let (_, ws) = workspace(TONES);
        let mut host = tones_host();
        compute(&mut host, &ws).unwrap();
        let view = host.app.current.clone().unwrap();
        let rows = want["rows"].as_u64().unwrap() as usize;
        assert_eq!((view.rows, view.cols, view.samples()), (rows, 1024, 1024));
        assert_eq!(view.coi.len(), 1024);
        all_close(&view.f, &floats(&want["f"]), 1e-10, "view frequencies");

        // The generated script in a fresh Engine gives the exported arrays.
        let fresh = run_saved(&mut host, &ws);
        assert_eq!(fresh.array("wt").unwrap().dims().as_ref(), &[rows, 1024]);
        check_coefficients(&fresh, "wt", &want["wt"]);
        let f = real(&fresh, "f");
        all_close(&f, &floats(&want["f"]), 1e-10, "f");
        assert_eq!(f, view.f);
        let xrec = real(&fresh, "xrec");
        assert_eq!(xrec, view.rec);
        all_close(
            &every(&xrec, 16),
            &floats(&want["icwt_full"]),
            1e-10,
            "icwt",
        );
        // icwt of the full transform recovers the signal as well as the
        // reference inverse does.
        let x = real(&fresh, "x");
        let norm = |v: &[f64]| v.iter().map(|a| a * a).sum::<f64>().sqrt();
        let error: Vec<f64> = xrec.iter().zip(&x).map(|(a, b)| a - b).collect();
        let relerr = norm(&error) / norm(&x);
        let bound = want["icwt_full_relerr"].as_f64().unwrap();
        assert!(relerr <= bound * (1. + 1e-6), "{relerr} > {bound}");
        assert!(relerr < 0.01);
        assert_eq!(view.x, x);

        // Peaks of the middle column lie within one voice of the true tones.
        let mut peaks = Vec::new();
        let column: Vec<f64> = (0..rows).map(|r| view.image[512 * rows + r]).collect();
        for (r, w) in column.windows(3).enumerate() {
            if w[1] > w[0] && w[1] >= w[2] && w[1] > 0.2 {
                peaks.push(view.f[r + 1]);
            }
        }
        peaks.sort_by(f64::total_cmp);
        assert_eq!(peaks.len(), 2, "{peaks:?}");
        for (peak, tone) in peaks.iter().zip(floats(&reference["tones"])) {
            assert!((peak / tone).log2().abs() <= 0.1, "{peak} vs {tone}");
        }
        // Readout: magnitude at the 90 Hz tone in the middle is about 0.5.
        let m = view.magnitude(0.5, peaks[1]).unwrap();
        assert!((m - 0.5).abs() < 0.05, "{m}");
        assert!(view.magnitude(-1., 40.).is_none());

        // The script holds the transform, plot and inverse calls.
        let script = host.app.script(&ws).unwrap();
        for part in [
            "cwt(wtf_x, 'morse', wtf_fs, 'VoicesPerOctave', 10)",
            "imagesc(wtf_t, log2(wtf_f), abs(wtf_wt))",
            "log2(wtf_coi)",
            "icwt(wtf_wt, 'morse', 'VoicesPerOctave', 10, 'SignalMean', mean(wtf_x))",
        ] {
            assert!(script.contains(part), "{part}\n{script}");
        }
        let results = host.app.results();
        assert!(
            results
                .iter()
                .any(|(k, v)| *k == "Frequency range shown" && v.ends_with("Hz"))
        );
    }

    #[test]
    fn wavelet_tf_analyzer_region_reconstruction_matches_reference() {
        let reference = reference();
        let want = &reference["cwt"];
        let (_, ws) = workspace(TONES);
        let mut host = tones_host();
        host.app.set_region(Some(Region {
            t: [0.75, 0.25],
            f: [130., 60.],
        }));
        assert_eq!(
            host.app.settings.region,
            Some(["0.25", "0.75", "60", "130"].map(String::from))
        );
        compute(&mut host, &ws).unwrap();
        let script = host.app.script(&ws).unwrap();
        assert!(script.contains("icwt(wtf_keep, 'morse', wtf_f, [60 130], 'VoicesPerOctave', 10)"));
        let fresh = run_saved(&mut host, &ws);
        let xrec = real(&fresh, "xrec");
        all_close(
            &every(&xrec, 16),
            &floats(&want["icwt_region"]),
            1e-10,
            "region",
        );
        let view = host.app.current.as_ref().unwrap();
        assert_eq!(view.rec, xrec);
        let ratio = want["region_energy_ratio"].as_f64().unwrap();
        assert!((view.ratio - ratio).abs() < 1e-9, "{}", view.ratio);
        assert!(
            host.app
                .results()
                .iter()
                .any(|(k, v)| *k == "Reconstruction energy ratio" && v.starts_with("0.098"))
        );
        // Bad boxes are refused before a run.
        host.app.settings.region = Some(["0.5", "0.5", "60", "130"].map(String::from));
        assert!(host.request(&ws).is_err());
        host.app.settings.region = Some(["0", "1", "-1", "130"].map(String::from));
        assert!(host.request(&ws).is_err());
    }

    #[test]
    fn wavelet_tf_analyzer_amor_limits_and_wsst_match_reference() {
        let reference = reference();
        let (_, ws) = workspace(TONES);
        // CWT, amor, 12 voices, 20 to 200 Hz.
        let mut host = tones_host();
        host.app.settings.wavelet = Wavelet::Amor;
        host.app.settings.voices = "12".into();
        host.app.settings.f_min = "20".into();
        host.app.settings.f_max = "200".into();
        compute(&mut host, &ws).unwrap();
        let want = &reference["cwt_amor_limits"];
        let fresh = run_saved(&mut host, &ws);
        all_close(&real(&fresh, "f"), &floats(&want["f"]), 1e-10, "amor f");
        check_coefficients(&fresh, "wt", &want["wt"]);
        assert!(
            host.app
                .script(&ws)
                .unwrap()
                .contains("'FrequencyLimits', [20 200]")
        );

        // Synchrosqueezed, amor, 32 voices: no cone of influence.
        let want = &reference["wsst"];
        let mut host = tones_host();
        host.app.set_transform(Transform::Wsst);
        assert_eq!(host.app.settings.voices, "32");
        assert_eq!(host.app.settings.wavelet, Wavelet::Amor);
        compute(&mut host, &ws).unwrap();
        let view = host.app.current.clone().unwrap();
        assert_eq!(view.rows, want["rows"].as_u64().unwrap() as usize);
        assert!(view.coi.is_empty());
        let fresh = run_saved(&mut host, &ws);
        all_close(&real(&fresh, "f"), &floats(&want["f"]), 1e-10, "wsst f");
        let (re, im) = complex(&fresh, "wt");
        let abs_sum: f64 = re.iter().zip(&im).map(|(a, b)| a.hypot(*b)).sum();
        let expected = want["abs_sum"].as_f64().unwrap();
        assert!((abs_sum - expected).abs() <= 1e-8 * expected, "{abs_sum}");
        all_close(
            &every(&real(&fresh, "xrec"), 16),
            &floats(&want["iwsst_full"]),
            1e-9,
            "iwsst",
        );
        // The 60-130 Hz band over the whole time span.
        host.app.set_region(Some(Region {
            t: [0., 1.],
            f: [60., 130.],
        }));
        compute(&mut host, &ws).unwrap();
        let fresh = run_saved(&mut host, &ws);
        all_close(
            &every(&real(&fresh, "xrec"), 16),
            &floats(&want["iwsst_region"]),
            1e-9,
            "iwsst region",
        );
        // Morse is a CWT-only wavelet.
        host.app.settings.wavelet = Wavelet::Morse;
        assert!(host.request(&ws).is_err());
    }

    #[test]
    fn wavelet_tf_analyzer_export_names_are_checked_and_atomic() {
        let (engine, ws) = workspace(&format!(
            "{TONES} wtf_x = 7; wtf_wt = 8; c = [1 2; 3 4]; z = [1 NaN 3 4 5 6 7 8]; s = 1:4;"
        ));
        let mut host = tones_host();
        // Temporaries never clobber workspace names; an output may reuse the
        // signal's own name.
        host.app.reconstruction.name = "x".into();
        compute(&mut host, &ws).unwrap();
        let script = host.app.script(&ws).unwrap();
        assert!(script.contains("wtf_x1 = double(reshape(x, 1, []))"));
        let code = match host.export(&ws).unwrap() {
            toolkits::Action::ExportScript(s) => s,
            _ => panic!("wrong export"),
        };
        let mut target = engine.clone();
        target.execute(&code).unwrap();
        assert_eq!(real(&target, "x"), host.app.current.as_ref().unwrap().rec);
        assert_eq!(real(&target, "wtf_x"), [7.]);
        assert_eq!(real(&target, "wtf_wt"), [8.]);
        assert!(target.array("wt").is_some() && target.array("f").is_some());
        assert_eq!(
            host.app.exported(&ws),
            ["wt", "f", "x"].map(String::from).to_vec()
        );
        for bad in [
            "mrexp_old",
            "mrexp_had",
            "matrust_export_error",
            "mrexp_complete",
            "1bad",
            "for",
            "wt);bad=1;%",
            "",
        ] {
            host.app.coefficients.name = bad.into();
            assert!(host.app.script(&ws).is_err(), "{bad:?}");
        }
        host.app.coefficients.name = "f".into();
        assert!(host.app.script(&ws).unwrap_err().contains("duplicate"));
        // An unticked output is neither checked nor exported.
        host.app.coefficients.export = false;
        assert!(!host.app.script(&ws).unwrap().contains("\nf = wtf_wt;"));
        assert_eq!(host.app.exported(&ws).len(), 2);
        host.app.frequencies.export = false;
        host.app.reconstruction.export = false;
        assert!(host.app.script(&ws).is_err());
        // A failing export restores the earlier values.
        host.app.coefficients = apps::wavelet_tf_analyzer::Output {
            name: "result".into(),
            export: true,
        };
        compute(&mut host, &ws).unwrap();
        let code = match host.export(&ws).unwrap() {
            toolkits::Action::ExportScript(s) => s,
            _ => unreachable!(),
        };
        let mut target = engine.clone();
        target
            .execute("x = [NaN 1 2 3 4 5 6 7 8]; result = 123;")
            .unwrap();
        assert!(target.execute(&code).is_err());
        assert_eq!(real(&target, "result"), [123.]);
        // Signals that are not usable vectors are refused before a run.
        for source in ["missing", "c", "z", "s", "x);error('bad');%", ""] {
            host.app.settings.signal = source.into();
            assert!(host.request(&ws).is_err(), "{source}");
        }
    }

    #[test]
    fn wavelet_tf_analyzer_fields_are_validated_and_errors_keep_the_view() {
        let (_, ws) = workspace(TONES);
        let mut host = tones_host();
        compute(&mut host, &ws).unwrap();
        let previous = host.app.current.as_ref().unwrap().generation;
        let base = host.app.settings.clone();
        type Set = fn(&mut apps::wavelet_tf_analyzer::Settings, &str);
        let cases: [(Set, &[&str]); 6] = [
            (
                |s, v| s.voices = v.into(),
                &["0", "49", "1.5", "2^3", "10); x=1; %", "NaN"],
            ),
            (
                |s, v| s.rate = v.into(),
                &["-1", "0", "Inf", "1e13", "1024\nerror('x')"],
            ),
            (|s, v| s.f_min = v.into(), &["0", "-5", "300", "abc"]),
            (|s, v| s.f_max = v.into(), &["513", "10", "2e3"]),
            (|s, v| s.gamma = v.into(), &["0.5", "21", "x"]),
            (|s, v| s.time_bandwidth = v.into(), &["2", "121", "60;"]),
        ];
        for (set, values) in cases {
            for value in values {
                host.app.settings = base.clone();
                if host.app.settings.f_min.is_empty() {
                    host.app.settings.f_min = "20".into();
                    host.app.settings.f_max = "200".into();
                }
                set(&mut host.app.settings, value);
                assert!(host.request(&ws).is_err(), "{value:?}");
                assert_eq!(host.app.current.as_ref().unwrap().generation, previous);
            }
        }
        host.app.settings = base.clone();
        host.app.set_transform(Transform::Wsst);
        for bad in ["11", "8", "50"] {
            host.app.settings.voices = bad.into();
            assert!(host.request(&ws).is_err(), "{bad}");
        }
        // Stop is shown in the status line and keeps the last scalogram until
        // an input changes.
        host.app.settings = base.clone();
        let ctx = egui::Context::default();
        host.app.stop();
        host.refresh(&ctx, &ws);
        assert_eq!(host.status().1, toolkits::AppStatus::Error);
        assert!(host.status().0.contains("stopped"));
        assert!(!host.running());
        assert_eq!(host.app.current.as_ref().unwrap().generation, previous);
        host.app.settings.voices = "12".into();
        host.app.prepare(&ws);
        assert!(host.app.script(&ws).is_ok());
        // An engine error reaches the status line; the view stays.
        host.app.settings = base;
        host.app.settings.region = Some(["0", "1", "500", "510"].map(String::from));
        let deadline = Instant::now() + std::time::Duration::from_secs(60);
        loop {
            host.refresh(&ctx, &ws);
            if !host.running() || Instant::now() > deadline {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        host.refresh(&ctx, &ws);
        if host.status().1 == toolkits::AppStatus::Error {
            assert_eq!(host.app.current.as_ref().unwrap().generation, previous);
        }
    }

    #[test]
    fn wavelet_tf_analyzer_tool_tab_headless_empty_64_and_1e5_samples() {
        let kind = AppKind::WaveletTfAnalyzer;
        let tab = kind.tab();
        assert_eq!(AppKind::from_tab(tab), Some(kind));
        assert_eq!(
            serde_json::to_string(&tab).unwrap(),
            "\"wavelet_tf_analyzer\""
        );
        let decoded: matrust::session::ToolTab =
            serde_json::from_str("\"wavelet_tf_analyzer\"").unwrap();
        assert_eq!(decoded, tab);
        assert!(kind.is_built() && AppKind::ALL.contains(&kind));
        let (_, ws) = workspace(
            "s64 = sin(2*pi*0.1*(0:63)) + 0.3*cos(2*pi*0.3*(0:63)); \
             n = 1e5; s1e5 = sin(2*pi*0.01*(0:n-1)) + 0.5*sin(2*pi*(0.02 + 0.2*(0:n-1)/n).*(0:n-1));",
        );
        let workers = std::thread::available_parallelism()
            .map_or(1, |n| n.get())
            .min(8);
        for signal in ["", "s64", "s1e5"] {
            let mut computed = None;
            if !signal.is_empty() {
                let mut host = Host::new(WaveletTfAnalyzer::default());
                host.app.settings.signal = signal.into();
                if signal == "s1e5" {
                    host.app.settings.f_min = "0.005".into();
                    host.app.settings.f_max = "0.45".into();
                }
                // Release workload, 1 and N workers (isolated pools, sequential).
                for count in [1, workers] {
                    let pool = rayon::ThreadPoolBuilder::new()
                        .num_threads(count)
                        .build()
                        .unwrap();
                    let elapsed = pool.install(|| {
                        let start = Instant::now();
                        compute(&mut host, &ws).unwrap();
                        start.elapsed()
                    });
                    eprintln!("wavelet_tf_analyzer {signal} workers={count} elapsed={elapsed:?}");
                }
                let view = host.app.current.as_ref().unwrap();
                if signal == "s1e5" {
                    assert_eq!(view.samples(), 100_000);
                    assert!(view.cols <= apps::wavelet_tf_analyzer::VIEW_COLUMNS);
                    assert_eq!(view.cols, 100_000usize.div_ceil(98));
                } else {
                    assert_eq!(view.cols, 64);
                }
                computed = Some(host.app.settings.clone());
            }
            for width in [820., 1600.] {
                let ctx = egui::Context::default();
                let mut desktop = Workspace::with_context(ctx.clone(), true);
                desktop.toolkits.open_tool(Tool::App(kind));
                if let Some(settings) = &computed {
                    let host = &mut desktop.toolkits.apps.wavelet_tf;
                    host.app.settings = settings.clone();
                    compute(host, &ws).unwrap();
                }
                let output = frame_at(&mut desktop, &ctx, egui::vec2(width, 950.), vec![]);
                assert!(!output.shapes.is_empty());
                assert_eq!(desktop.toolkits.selected_tool(), Some(Tool::App(kind)));
                desktop.close_tool_tab(Tool::App(kind));
            }
        }
    }
}
